from pathlib import Path
import re,json
R=Path(__file__).resolve().parents[5];D=Path(__file__).resolve().parent
files={x: (R/f'chapters/E07/E07_{x}.html').read_text() for x in ['a','b','c','d','pop1','pop2']};changes=[]
def rep(old,new,keys=None):
 count=0
 for k in keys or files:
  n=files[k].count(old)
  if n:files[k]=files[k].replace(old,new);count+=n
 if not count:print('ABSENT',old[:85])
 else:changes.append(dict(kind='literal',count=count,old=old,new=new))
def para(k,needle,new):
 pat=r'<p(?:\s[^>]*)?>[^\n]*?</p>'; matches=[m for m in re.finditer(pat,files[k]) if needle in m.group()]
 assert matches,(k,needle)
 for m in reversed(matches):
  old=m.group();files[k]=files[k][:m.start()]+new+files[k][m.end():];changes.append(dict(kind='paragraph',file=k,old=old,new=new))
def pop(k,key,title,body):
 pat=r'<template data-pop="'+re.escape(key)+r'"[^>]*>.*?</template>'
 new=f'<template data-pop="{key}" data-title="{title}">\n{body}\n</template>'
 m=re.search(pat,files[k],re.S);assert m,key;changes.append(dict(kind='popup',file=k,old=m.group(),new=new));files[k]=files[k][:m.start()]+new+files[k][m.end():]
